const DEG = Math.PI / 180;
const SURF_W = 5.2;
const SURF_H = 3.2;
const IMG_W = 1.7;
const IMG_H = 1.35;
const IMG_DIST = 1.15;
const P_LOCAL = new THREE.Vector3(3.8, 2.35, 0);

let tiltDeg = 25;
let mode2D = false;
let cameraCenter = new THREE.Vector3(-3.0, 1.2, 2.1);
let imageBasis = {
  center: new THREE.Vector3(),
  u: new THREE.Vector3(1, 0, 0),
  v: new THREE.Vector3(0, 1, 0),
  dir: new THREE.Vector3(0, 0, -1),
