};
let Hnorm = [[1,0,0],[0,1,0],[0,0,1]];

const fullGroup = new THREE.Group();
const homoGroup = new THREE.Group();
scene.add(fullGroup);
scene.add(homoGroup);
homoGroup.visible = false;

const matDark = new THREE.LineBasicMaterial({ color: 0x111111 });
