const matGreyDash = new THREE.LineDashedMaterial({ color: 0xdddddd, dashSize: 0.18, gapSize: 0.10, transparent: true, opacity: 0.9 });
const matCyanDash = new THREE.LineDashedMaterial({ color: 0x00e5e5, dashSize: 0.18, gapSize: 0.11 });
const matCyan = new THREE.MeshBasicMaterial({ color: 0x00e5e5 });
const matCyanOuter = new THREE.MeshBasicMaterial({ color: 0x111111 });
const matPlane = new THREE.MeshBasicMaterial({ color: 0xcfcfcf, side: THREE.DoubleSide, transparent: true, opacity: 0.56 });
const matImgPlane = new THREE.MeshBasicMaterial({ color: 0xcfcfcf, side: THREE.DoubleSide, transparent: true, opacity: 0.55 });

function makeLine(material, dashed = false) {
  const line = new THREE.Line(new THREE.BufferGeometry(), material);
  if (dashed) line.computeLineDistances();
  return line;
}

function setLinePoints(line, pts) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  if (line.material && line.material.isLineDashedMaterial) line.computeLineDistances();
}

function makeQuadMesh(material) {
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(new Array(18).fill(0), 3));
  geom.setIndex([0, 1, 2, 0, 2, 3]);
  return new THREE.Mesh(geom, material);
}

function setQuad(mesh, corners) {
  const arr = [
    corners[0].x, corners[0].y, corners[0].z,
    corners[1].x, corners[1].y, corners[1].z,
    corners[2].x, corners[2].y, corners[2].z,
    corners[3].x, corners[3].y, corners[3].z
  ];
  mesh.geometry.dispose();
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
  geom.setIndex([0, 1, 2, 0, 2, 3]);
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
