}

function localToWorld(p) {
  const th = tiltDeg * DEG;
  const c = Math.cos(th), s = Math.sin(th);
  return new THREE.Vector3(p.x, p.y * c - p.z * s, p.y * s + p.z * c);
}

function basisX() {
  return new THREE.Vector3(1, 0, 0);
}

function basisY() {
  const th = tiltDeg * DEG;
  return new THREE.Vector3(0, Math.cos(th), Math.sin(th));
}

function basisZ() {
  const th = tiltDeg * DEG;
  return new THREE.Vector3(0, -Math.sin(th), Math.cos(th));
}

function makePoint(radiusOuter, radiusInner) {
  const g = new THREE.Group();
