}

const worldXArrow = new THREE.ArrowHelper(new THREE.Vector3(1, 0, 0), new THREE.Vector3(), 1.7, 0xff1010, 0.28, 0.16);
const worldYArrow = new THREE.ArrowHelper(new THREE.Vector3(0, 1, 0), new THREE.Vector3(), 1.4, 0xff1010, 0.28, 0.16);
