const camLabel = addLabel('Camera<br>center', cameraCenter.clone(), { fontSize: '34px', color: '#000' });
const camPlaneLabel = addLabel('Camera plane', new THREE.Vector3(), { fontSize: '38px', color: '#000' });
camPlaneLabel.div.style.rotate = '-43deg';
const imgPointLabel = addLabel('<i>(x,y)</i>', new THREE.Vector3(), { fontSize: '24px', color: '#00dfe8', bold: true });
const worldPointLabel = addLabel('<i>(X,Y,0)</i>', new THREE.Vector3(), { fontSize: '30px', color: '#00dfe8', bold: true });
const planarLabel = addLabel('planar surface', new THREE.Vector3(), { fontSize: '34px', color: '#000' });
const labelX = addLabel('<i>X</i>', new THREE.Vector3(), { fontSize: '28px', color: '#111' });
const labelY = addLabel('<i>Y</i>', new THREE.Vector3(), { fontSize: '28px', color: '#111' });
const labelZ = addLabel('<i>Z</i>', new THREE.Vector3(), { fontSize: '28px', color: '#111' });
const labelImgX = addLabel('<i>x</i>', new THREE.Vector3(), { fontSize: '26px', color: '#111' });
