const fullLabels = [camLabel, camPlaneLabel, imgPointLabel, worldPointLabel, planarLabel, labelX, labelY, labelZ, labelImgX, labelImgY];

const h2dLabels = [];

function makePanelRect(cx, cy, w, h, fillColor) {
  const geom = new THREE.BufferGeometry();
  const z = 0;
  const pts = [
    new THREE.Vector3(cx - w / 2, cy - h / 2, z),
    new THREE.Vector3(cx + w / 2, cy - h / 2, z),
    new THREE.Vector3(cx + w / 2, cy + h / 2, z),
