// world point → cyan SphereGeometry(0.115) with black outer rim at local P=(3.8,2.35,0)
// projection ray → cyan LineDashedMaterial from camera center through image point to world point
// frustum rays → four black LineDashedMaterial rays through image-plane corners and onward
// hidden construction rays → pale gray LineDashedMaterial rays behind/near the image plane
// projected image grid → faint cyan dashed lines induced on the camera plane by plane-grid samples
// 2D homography view → two flat coordinate rectangles with grids, cyan points, and red arrow labeled H
// homography matrix panel → live HTML pre updated from the current camera/plane geometry

const DEG = Math.PI / 180;
const SURF_W = 5.2;
const SURF_H = 3.2;
const IMG_W = 1.7;
