const matDark = new THREE.LineBasicMaterial({ color: 0x111111, linewidth: 3 });
const matBlackDash = new THREE.LineDashedMaterial({ color: 0x111111, dashSize: 0.28, gapSize: 0.16, linewidth: 3 });
const matGreyDash = new THREE.LineDashedMaterial({ color: 0xdddddd, dashSize: 0.24, gapSize: 0.15, transparent: true, opacity: 0.85 });
const matCyanDash = new THREE.LineDashedMaterial({ color: 0x00e5e5, dashSize: 0.26, gapSize: 0.15, linewidth: 3 });
const matCyan = new THREE.MeshBasicMaterial({ color: 0x00e5e5 });
const matCyanOuter = new THREE.MeshBasicMaterial({ color: 0x111111 });
const matPlane = new THREE.MeshBasicMaterial({ color: 0xcfcfcf, side: THREE.DoubleSide, transparent: true, opacity: 0.58 });
const matImgPlane = new THREE.MeshBasicMaterial({ color: 0xcfcfcf, side: THREE.DoubleSide, transparent: true, opacity: 0.55 });

function nonEmptyGeometry(points) {
  const pts = points && points.length >= 2 ? points : [new THREE.Vector3(), new THREE.Vector3()];
  return new THREE.BufferGeometry().setFromPoints(pts);
}

function makeLine(material, dashed = false, loop = false) {
  const line = loop
    ? new THREE.LineLoop(nonEmptyGeometry([new THREE.Vector3(), new THREE.Vector3(0.001, 0, 0), new THREE.Vector3(0.001, 0.001, 0), new THREE.Vector3(0, 0.001, 0)]), material)
    : new THREE.Line(nonEmptyGeometry([new THREE.Vector3(), new THREE.Vector3(0.001, 0, 0)]), material);
  if (dashed) line.computeLineDistances();
  return line;
}

function setLinePoints(line, pts) {
  const safePts = pts && pts.length >= 2 ? pts : [new THREE.Vector3(), new THREE.Vector3(0.001, 0, 0)];
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(safePts);
  old?.dispose?.();
  if (line.material && line.material.isLineDashedMaterial) line.computeLineDistances();
}

function makeQuadMesh(material) {
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute([
    0, 0, 0, 0.001, 0, 0, 0.001, 0.001, 0, 0, 0.001, 0
  ], 3));
  geom.setIndex([0, 1, 2, 0, 2, 3]);
  geom.computeBoundingSphere();
  return new THREE.Mesh(geom, material);
}

function setQuad(mesh, corners) {
  const arr = [
    corners[0].x, corners[0].y, corners[0].z,
    corners[1].x, corners[1].y, corners[1].z,
    corners[2].x, corners[2].y, corners[2].z,
    corners[3].x, corners[3].y, corners[3].z
  ];
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
  geom.setIndex([0, 1, 2, 0, 2, 3]);
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
  const old = mesh.geometry;
  mesh.geometry = geom;
  old?.dispose?.();
}

function localToWorld(p) {
  const th = tiltDeg * DEG;
  const c = Math.cos(th), s = Math.sin(th);
  return new THREE.Vector3(p.x, p.y * c - p.z * s, p.y * s + p.z * c);
}

function basisX() {
  return new THREE.Vector3(1, 0, 0);
}

function basisY() {
  const th = tiltDeg * DEG;
  return new THREE.Vector3(0, Math.cos(th), Math.sin(th));
}

function basisZ() {
  const th = tiltDeg * DEG;
  return new THREE.Vector3(0, -Math.sin(th), Math.cos(th));
}

function makePoint(radiusOuter, radiusInner) {
  const g = new THREE.Group();
  g.add(new THREE.Mesh(new THREE.SphereGeometry(radiusOuter, 32, 18), matCyanOuter));
  g.add(new THREE.Mesh(new THREE.SphereGeometry(radiusInner, 32, 18), matCyan));
  return g;
}

