const img2DLines = [];
const src2DLines = [];
for (let i = 0; i < 8; i++) {
  const li = makeLine(new THREE.LineBasicMaterial({ color: 0x00bfc7, transparent: true, opacity: 0.70 }));
  const ls = makeLine(new THREE.LineBasicMaterial({ color: 0x777777, transparent: true, opacity: 0.58 }));
  img2DLines.push(li);
  src2DLines.push(ls);
  img2DGrid.add(li);
