let fullLabels = [];
let h2dLabels = [];

function computeImageBasis() {
  const centerPlane = localToWorld(new THREE.Vector3(SURF_W / 2, SURF_H / 2, 0));
  const dir = centerPlane.clone().sub(cameraCenter).normalize();
  let upHint = new THREE.Vector3(0, 1, 0);
  if (Math.abs(upHint.dot(dir)) > 0.94) upHint.set(0, 0, 1);
  const u = new THREE.Vector3().crossVectors(upHint, dir).normalize();
  const v = new THREE.Vector3().crossVectors(dir, u).normalize();
  const center = cameraCenter.clone().addScaledVector(dir, IMG_DIST);
  const corners = [
    center.clone().addScaledVector(u, -IMG_W / 2).addScaledVector(v, -IMG_H / 2),
    center.clone().addScaledVector(u, IMG_W / 2).addScaledVector(v, -IMG_H / 2),
    center.clone().addScaledVector(u, IMG_W / 2).addScaledVector(v, IMG_H / 2),
    center.clone().addScaledVector(u, -IMG_W / 2).addScaledVector(v, IMG_H / 2)
  ];
  imageBasis = { center, u, v, dir, corners };
}

function rayPlaneIntersectionForLocal(localPoint) {
  const Q = localToWorld(localPoint);
  const den = Q.clone().sub(cameraCenter).dot(imageBasis.dir);
  const t = IMG_DIST / den;
  return cameraCenter.clone().lerp(Q, t);
}

function homographyMatrix() {
  const ex = basisX();
  const ey = basisY();
  const oMinusC = localToWorld(new THREE.Vector3(0, 0, 0)).sub(cameraCenter);
  const H = [
    [IMG_DIST * imageBasis.u.dot(ex), IMG_DIST * imageBasis.u.dot(ey), IMG_DIST * imageBasis.u.dot(oMinusC)],
    [IMG_DIST * imageBasis.v.dot(ex), IMG_DIST * imageBasis.v.dot(ey), IMG_DIST * imageBasis.v.dot(oMinusC)],
    [imageBasis.dir.dot(ex), imageBasis.dir.dot(ey), imageBasis.dir.dot(oMinusC)]
  ];
  const s = Math.abs(H[2][2]) > 1e-8 ? H[2][2] : 1;
  Hnorm = H.map(row => row.map(x => x / s));
  return Hnorm;
}

function applyH(X, Y) {
  const h = Hnorm;
  const w = h[2][0] * X + h[2][1] * Y + h[2][2];
  return new THREE.Vector2(
    (h[0][0] * X + h[0][1] * Y + h[0][2]) / w,
    (h[1][0] * X + h[1][1] * Y + h[1][2]) / w
  );
}

function formatH(H) {
  return H.map(row => '[ ' + row.map(v => {
    const av = Math.abs(v) < 0.0005 ? 0 : v;
    return av.toFixed(3).padStart(7, ' ');
  }).join('  ') + ' ]').join('\n');
}

function update2DView() {
  const imgCx = -1.75, imgCy = 0.35;
  const srcCx = 1.75, srcCy = 0.35;
  const srcW = 2.05, srcH = 1.18;
  const srcScaleX = srcW / SURF_W;
  const srcScaleY = srcH / SURF_H;
  const imgScale = 0.78;
  let idx = 0;

  for (let i = 1; i <= 4; i++) {
    const X = SURF_W * i / 5;
    const x0 = srcCx - srcW / 2 + X * srcScaleX;
    setLinePoints(src2DLines[idx], [
      new THREE.Vector3(x0, srcCy - srcH / 2, 0.01),
      new THREE.Vector3(x0, srcCy + srcH / 2, 0.01)
    ]);
    const a = applyH(X, 0);
    const b = applyH(X, SURF_H);
    setLinePoints(img2DLines[idx], [
      new THREE.Vector3(imgCx + a.x * imgScale, imgCy + a.y * imgScale, 0.02),
      new THREE.Vector3(imgCx + b.x * imgScale, imgCy + b.y * imgScale, 0.02)
    ]);
    idx++;
  }

  for (let j = 1; j <= 4; j++) {
    const Y = SURF_H * j / 5;
    const y0 = srcCy - srcH / 2 + Y * srcScaleY;
    setLinePoints(src2DLines[idx], [
      new THREE.Vector3(srcCx - srcW / 2, y0, 0.01),
      new THREE.Vector3(srcCx + srcW / 2, y0, 0.01)
    ]);
    const a = applyH(0, Y);
    const b = applyH(SURF_W, Y);
    setLinePoints(img2DLines[idx], [
      new THREE.Vector3(imgCx + a.x * imgScale, imgCy + a.y * imgScale, 0.02),
      new THREE.Vector3(imgCx + b.x * imgScale, imgCy + b.y * imgScale, 0.02)
    ]);
    idx++;
  }

  const p = applyH(P_LOCAL.x, P_LOCAL.y);
  const srcPos = new THREE.Vector3(srcCx - srcW / 2 + P_LOCAL.x * srcScaleX, srcCy - srcH / 2 + P_LOCAL.y * srcScaleY, 0.06);
  const imgPos = new THREE.Vector3(imgCx + p.x * imgScale, imgCy + p.y * imgScale, 0.06);
  src2DPoint.position.copy(srcPos);
  img2DPoint.position.copy(imgPos);

  if (src2DPointLabel) src2DPointLabel.pos.copy(srcPos.clone().add(new THREE.Vector3(0.30, 0.15, 0)));
  if (img2DPointLabel) img2DPointLabel.pos.copy(imgPos.clone().add(new THREE.Vector3(0.24, 0.14, 0)));
}

function updateScene() {
  computeImageBasis();
  const ex = basisX(), ey = basisY(), ez = basisZ();

  const surfaceCorners = [
    localToWorld(new THREE.Vector3(0, 0, 0)),
    localToWorld(new THREE.Vector3(SURF_W, 0, 0)),
    localToWorld(new THREE.Vector3(SURF_W, SURF_H, 0)),
    localToWorld(new THREE.Vector3(0, SURF_H, 0))
  ];
  setQuad(surfaceMesh, surfaceCorners);
  setLinePoints(surfaceOutline, surfaceCorners);

  cameraHandle.position.copy(cameraCenter);
  setQuad(imagePlaneMesh, imageBasis.corners);
  setLinePoints(imageOutline, imageBasis.corners);

  const Pworld = localToWorld(P_LOCAL);
  const pImg = rayPlaneIntersectionForLocal(P_LOCAL);
  worldPoint.position.copy(Pworld);
  imagePoint.position.copy(pImg);

  setLinePoints(mainRay, [cameraCenter.clone(), pImg.clone(), Pworld.clone()]);
  for (let i = 0; i < 4; i++) {
    const far = cameraCenter.clone().add(imageBasis.corners[i].clone().sub(cameraCenter).multiplyScalar(6.4));
    setLinePoints(frustumRays[i], [cameraCenter.clone(), imageBasis.corners[i].clone(), far]);
  }

  const hiddenTargets = [
    localToWorld(new THREE.Vector3(0.45, 2.95, 0)),
    localToWorld(new THREE.Vector3(1.35, 0.45, 0)),
    localToWorld(new THREE.Vector3(2.15, 1.6, 0))
  ];
  for (let i = 0; i < hiddenRays.length; i++) {
    const q = hiddenTargets[i];
    const den = q.clone().sub(cameraCenter).dot(imageBasis.dir);
    const t = IMG_DIST / den;
    const pi = cameraCenter.clone().lerp(q, t);
    setLinePoints(hiddenRays[i], [cameraCenter.clone(), pi, q]);
  }

  let gi = 0;
  for (let i = 1; i <= 4; i++) {
    const X = SURF_W * i / 5;
    setLinePoints(projectedGridLines[gi++], [
      rayPlaneIntersectionForLocal(new THREE.Vector3(X, 0, 0)),
      rayPlaneIntersectionForLocal(new THREE.Vector3(X, SURF_H, 0))
    ]);
  }
  for (let j = 1; j <= 4; j++) {
    const Y = SURF_H * j / 5;
    setLinePoints(projectedGridLines[gi++], [
      rayPlaneIntersectionForLocal(new THREE.Vector3(0, Y, 0)),
      rayPlaneIntersectionForLocal(new THREE.Vector3(SURF_W, Y, 0))
    ]);
  }

  const origin = surfaceCorners[0];
  worldXArrow.position.copy(origin);
  worldYArrow.position.copy(origin);
  worldZArrow.position.copy(origin);
  worldXArrow.setDirection(ex.clone().normalize());
  worldYArrow.setDirection(ey.clone().normalize());
  worldZArrow.setDirection(ez.clone().normalize());
  worldXArrow.setLength(1.7, 0.28, 0.16);
  worldYArrow.setLength(1.4, 0.28, 0.16);
  worldZArrow.setLength(1.2, 0.28, 0.16);

  const imgOrigin = imageBasis.corners[0].clone().addScaledVector(imageBasis.u, 0.22).addScaledVector(imageBasis.v, 0.20);
  imgXArrow.position.copy(imgOrigin);
  imgYArrow.position.copy(imgOrigin);
  imgXArrow.setDirection(imageBasis.u.clone().normalize());
  imgYArrow.setDirection(imageBasis.v.clone().normalize());
  imgXArrow.setLength(0.65, 0.17, 0.10);
  imgYArrow.setLength(0.62, 0.17, 0.10);

  homographyMatrix();
  document.getElementById('matrixH').textContent = formatH(Hnorm);
  document.getElementById('tiltVal').textContent = `${Math.round(tiltDeg)}°`;
  document.getElementById('pointReadout').textContent = `(X,Y,0) = (${P_LOCAL.x.toFixed(2)}, ${P_LOCAL.y.toFixed(2)}, 0)`;

  if (camLabel) {
    camLabel.pos.copy(cameraCenter.clone().add(new THREE.Vector3(-0.58, 0.20, 0.12)));
    camPlaneLabel.pos.copy(imageBasis.corners[3].clone().lerp(imageBasis.corners[2], 0.54).addScaledVector(imageBasis.v, 0.30));
    imgPointLabel.pos.copy(pImg.clone().addScaledVector(imageBasis.u, 0.28).addScaledVector(imageBasis.v, 0.12));
    worldPointLabel.pos.copy(Pworld.clone().add(new THREE.Vector3(0.33, 0.18, 0.08)));
    planarLabel.pos.copy(localToWorld(new THREE.Vector3(SURF_W * 0.96, SURF_H * 0.17, 0)).add(new THREE.Vector3(0.58, -0.08, 0.02)));
    labelX.pos.copy(origin.clone().addScaledVector(ex, 1.92).add(new THREE.Vector3(0.08, -0.02, 0)));
    labelY.pos.copy(origin.clone().addScaledVector(ey, 1.58).add(new THREE.Vector3(0.05, 0.05, 0.05)));
    labelZ.pos.copy(origin.clone().addScaledVector(ez, 1.34).add(new THREE.Vector3(-0.08, 0.03, 0.08)));
    labelImgX.pos.copy(imgOrigin.clone().addScaledVector(imageBasis.u, 0.78).addScaledVector(imageBasis.v, -0.08));
    labelImgY.pos.copy(imgOrigin.clone().addScaledVector(imageBasis.v, 0.76).addScaledVector(imageBasis.u, -0.08));
  }

  update2DView();
}

