  const srcScaleY = srcH / SURF_H;
  const imgScale = 0.78;
  let idx = 0;

  for (let i = 1; i <= 4; i++) {
    const X = SURF_W * i / 5;
    const x0 = srcCx - srcW / 2 + X * srcScaleX;
    setLinePoints(src2DLines[idx], [
      new THREE.Vector3(x0, srcCy - srcH / 2, 0.01),
      new THREE.Vector3(x0, srcCy + srcH / 2, 0.01)
    ]);
    const a = applyH(X, 0);
    const b = applyH(X, SURF_H);
    setLinePoints(img2DLines[idx], [
      new THREE.Vector3(imgCx + a.x * imgScale, imgCy + a.y * imgScale, 0.02),
      new THREE.Vector3(imgCx + b.x * imgScale, imgCy + b.y * imgScale, 0.02)
