function goToStep(i) {
  const step = steps[i];
  if (!step) return;
  document.getElementById('stepNarration').innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  const startTilt = tiltDeg;
  const endTilt = step.state.planeTilt;
  const want2D = step.state.projectionMode === '2D homography';
  if (want2D !== mode2D) setMode(want2D, true);

  const start = performance.now();
  const token = ++tweenToken;
  function tick(now) {
    if (token !== tweenToken) return;
    const t = Math.min(1, (now - start) / 650);
    const ease = t * t * (3 - 2 * t);
    tiltDeg = startTilt + (endTilt - startTilt) * ease;
    document.getElementById('planeTilt').value = String(Math.round(tiltDeg));
    updateScene();
    if (t < 1) {
      requestAnimationFrame(tick);
    } else {
      tiltDeg = endTilt;
      document.getElementById('planeTilt').value = String(endTilt);
      updateScene();
      if (want2D) set2DCameraView();
      else setFullCameraView();
    }
  }
  requestAnimationFrame(tick);
}
