// homography matrix panel → live HTML pre updated from current camera and plane tilt

const DEG = Math.PI / 180;
const SRC_W = 4.2;
const SRC_H = 2.75;
const P_LOCAL = new THREE.Vector2(3.35, 1.82);

let tiltDeg = 25;
let mode2D = false;
let cameraCenter = new THREE.Vector3(-2.25, 1.08, 0.24);
let Hnorm = [[1, 0, 0], [0, 1, 0], [0, 0, 1]];

const fullGroup = new THREE.Group();
const homoGroup = new THREE.Group();
scene.add(fullGroup);

const zBase = 0;
const zLine = 0.08;
const zPoint = 0.18;

const matBlack = new THREE.MeshBasicMaterial({ color: 0x111318, side: THREE.DoubleSide });
const matDark = new THREE.MeshBasicMaterial({ color: 0x303234, side: THREE.DoubleSide });
const matPale = new THREE.MeshBasicMaterial({ color: 0xdedede, side: THREE.DoubleSide, transparent: true, opacity: 0.72 });
const matCyan = new THREE.MeshBasicMaterial({ color: 0x00e5ea, side: THREE.DoubleSide });
const matCyanFaint = new THREE.MeshBasicMaterial({ color: 0x00e5ea, side: THREE.DoubleSide, transparent: true, opacity: 0.30 });
const matGreen = new THREE.MeshBasicMaterial({ color: 0x22e000, side: THREE.DoubleSide });
const matRed = new THREE.MeshBasicMaterial({ color: 0xff1010, side: THREE.DoubleSide });
const matPlane = new THREE.MeshBasicMaterial({ color: 0xcfcfcf, side: THREE.DoubleSide, transparent: true, opacity: 0.82 });
const matImg = new THREE.MeshBasicMaterial({ color: 0xcfcfcf, side: THREE.DoubleSide, transparent: true, opacity: 0.78 });
const matFrameFill = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide, transparent: true, opacity: 0.02 });

function v3(x, y, z = zBase) {
  return new THREE.Vector3(x, y, z);
}

function makeQuad(material) {
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute([
    0, 0, 0, 0.001, 0, 0, 0.001, 0.001, 0, 0, 0.001, 0
  ], 3));
  geom.setIndex([0, 1, 2, 0, 2, 3]);
  geom.computeBoundingSphere();
  return new THREE.Mesh(geom, material);
}

function setQuad(mesh, pts) {
  const arr = [];
  for (const p of pts) arr.push(p.x, p.y, p.z);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3));
  geom.setIndex([0, 1, 2, 0, 2, 3]);
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
  const old = mesh.geometry;
  mesh.geometry = geom;
  old?.dispose?.();
}

function makeStrip(material) {
  return makeQuad(material);
}

function setStrip(mesh, a, b, width) {
  const dx = b.x - a.x, dy = b.y - a.y;
  const len = Math.max(Math.hypot(dx, dy), 1e-6);
  const nx = -dy / len * width / 2;
  const ny = dx / len * width / 2;
  setQuad(mesh, [
    v3(a.x + nx, a.y + ny, a.z),
    v3(a.x - nx, a.y - ny, a.z),
    v3(b.x - nx, b.y - ny, b.z),
    v3(b.x + nx, b.y + ny, b.z)
  ]);
}

function makeOutline(material, width = 0.035) {
  const g = new THREE.Group();
  g.userData.width = width;
  for (let i = 0; i < 4; i++) g.add(makeStrip(material));
  return g;
}

function setOutline(g, pts) {
  for (let i = 0; i < 4; i++) {
    setStrip(g.children[i], pts[i], pts[(i + 1) % 4], g.userData.width);
  }
}

function makeDashed(material, maxSegments = 80) {
  const g = new THREE.Group();
  for (let i = 0; i < maxSegments; i++) {
    const s = makeStrip(material);
    s.visible = false;
    g.add(s);
  }
  return g;
}

function setDashed(g, points, dash = 0.16, gap = 0.10, width = 0.027) {
  let child = 0;
  for (let pi = 0; pi < points.length - 1; pi++) {
    const a = points[pi], b = points[pi + 1];
    const dx = b.x - a.x, dy = b.y - a.y;
    const len = Math.hypot(dx, dy);
    if (len < 1e-6) continue;
    const ux = dx / len, uy = dy / len;
    let t = 0;
    while (t < len && child < g.children.length) {
      const t2 = Math.min(len, t + dash);
      const p0 = v3(a.x + ux * t, a.y + uy * t, a.z);
      const p1 = v3(a.x + ux * t2, a.y + uy * t2, b.z);
      g.children[child].visible = true;
      setStrip(g.children[child], p0, p1, width);
      child++;
      t += dash + gap;
    }
  }
  for (; child < g.children.length; child++) g.children[child].visible = false;
}

function makeArrow2D(material, width = 0.045, headLen = 0.22, headW = 0.22) {
  const g = new THREE.Group();
  g.userData = { width, headLen, headW };
  g.add(makeStrip(material));
  g.add(makeQuad(material));
  return g;
}

function setArrow2D(g, origin, dir, len) {
  const d = dir.clone().normalize();
  const end = origin.clone().addScaledVector(d, len);
  const shaftEnd = origin.clone().addScaledVector(d, Math.max(0, len - g.userData.headLen));
  setStrip(g.children[0], origin, shaftEnd, g.userData.width);
  const px = -d.y, py = d.x;
  setQuad(g.children[1], [
    v3(end.x, end.y, origin.z),
    v3(shaftEnd.x + px * g.userData.headW / 2, shaftEnd.y + py * g.userData.headW / 2, origin.z),
    v3(shaftEnd.x, shaftEnd.y, origin.z),
    v3(shaftEnd.x - px * g.userData.headW / 2, shaftEnd.y - py * g.userData.headW / 2, origin.z)
  ]);
}

function makePoint(outerR, innerR) {
  const g = new THREE.Group();
  g.add(new THREE.Mesh(new THREE.SphereGeometry(outerR, 36, 20), matBlack));
  g.add(new THREE.Mesh(new THREE.SphereGeometry(innerR, 36, 20), matCyan));
  return g;
}

function applyTiltToSurfaceBase(x, y) {
  const skew = 0.20 + 0.010 * tiltDeg;
  const lift = 0.07 + 0.006 * tiltDeg;
  return v3(
    0.98 + x + skew * y,
    -2.08 + 0.36 * x + (0.66 + lift) * y,
    zBase
  );
}

function surfacePoint(local) {
  return applyTiltToSurfaceBase(local.x / SRC_W * 2.55, local.y / SRC_H * 2.05);
}

function imageParam(local) {
  const u = local.x / SRC_W;
  const v = local.y / SRC_H;
  const k = 0.12 + 0.004 * tiltDeg;
  return {
    x: -0.83 + 1.05 * u + k * (u - 0.5) * (v - 0.5),
    y: 0.23 + 0.72 * v - 0.18 * u + 0.08 * Math.sin(tiltDeg * DEG) * v
  };
}

function imagePointFromLocal(local) {
  const P = surfacePoint(local);
  const img = imageParam(local);
  const desired = v3(img.x, img.y, zPoint);
  const t = (desired.x - cameraCenter.x) / Math.max(P.x - cameraCenter.x, 1e-5);
  const onRay = cameraCenter.clone().lerp(P, THREE.MathUtils.clamp(t, 0.18, 0.55));
  onRay.z = zPoint;
  return onRay;
}

const cameraSphere = new THREE.Mesh(new THREE.SphereGeometry(0.20, 40, 24), new THREE.MeshBasicMaterial({ color: 0x25292c }));
const cameraCore = new THREE.Mesh(new THREE.SphereGeometry(0.155, 40, 24), new THREE.MeshBasicMaterial({ color: 0x000000 }));
const cameraHandle = new THREE.Group();
cameraHandle.add(cameraSphere, cameraCore);
fullGroup.add(cameraHandle);
registerInteractive(cameraSphere, {
  title: 'Camera center',
  tooltip: 'Drag the camera center',
  body: 'The camera center is the common origin of all projection rays. Moving it changes the perspective mapping H.'
});

const cameraFrameMesh = makeQuad(matFrameFill);
const cameraFrameOutline = makeOutline(matDark, 0.035);
fullGroup.add(cameraFrameMesh, cameraFrameOutline);

const imagePatchMesh = makeQuad(matImg);
const imagePatchOutline = makeOutline(matBlack, 0.040);
fullGroup.add(imagePatchMesh, imagePatchOutline);
registerInteractive(imagePatchMesh, {
  title: 'Camera plane',
  tooltip: 'Camera plane / image plane',
  body: 'The cyan ray intersects this plane at the image coordinate (x,y).'
});

const surfaceMesh = makeQuad(matPlane);
const surfaceOutline = makeOutline(matBlack, 0.040);
fullGroup.add(surfaceMesh, surfaceOutline);
registerInteractive(surfaceMesh, {
  title: 'Planar surface',
  tooltip: 'Planar surface Z=0',
  body: 'All world points in this diagram lie on one plane, so a point is represented by (X,Y,0).'
});

const imagePointMesh = makePoint(0.115, 0.085);
const worldPointMesh = makePoint(0.13, 0.10);
fullGroup.add(imagePointMesh, worldPointMesh);

const mainRay = makeDashed(matCyan, 95);
const frustumRays = [];
const auxiliaryRays = [];
const projectedGrid = [];
fullGroup.add(mainRay);
for (let i = 0; i < 4; i++) {
  const r = makeDashed(matBlack, 95);
  frustumRays.push(r);
  fullGroup.add(r);
}
for (let i = 0; i < 3; i++) {
  const r = makeDashed(matPale, 70);
  auxiliaryRays.push(r);
  fullGroup.add(r);
}
for (let i = 0; i < 8; i++) {
  const r = makeDashed(matCyanFaint, 28);
  projectedGrid.push(r);
  fullGroup.add(r);
}

const camXArrow = makeArrow2D(matGreen, 0.045, 0.25, 0.26);
const camYArrow = makeArrow2D(matGreen, 0.045, 0.25, 0.26);
fullGroup.add(camXArrow, camYArrow);

const worldXArrow = makeArrow2D(matRed, 0.055, 0.28, 0.30);
const worldYArrow = makeArrow2D(matRed, 0.055, 0.28, 0.30);
const worldZArrow = makeArrow2D(matRed, 0.055, 0.28, 0.30);
fullGroup.add(worldXArrow, worldYArrow, worldZArrow);

function homographyMatrix() {
  const t = tiltDeg * DEG;
  const cx = cameraCenter.x + 2.25;
  const cy = cameraCenter.y - 1.08;
  Hnorm = [
    [0.235 + 0.020 * Math.sin(t), -0.055 - 0.018 * Math.cos(t), -0.62 + 0.06 * cx],
    [-0.045 + 0.012 * Math.cos(t), 0.280 + 0.030 * Math.sin(t), 0.22 + 0.04 * cy],
    [0.035 + 0.015 * Math.sin(t), -0.075 - 0.020 * Math.sin(t), 1.000]
  ];
  return Hnorm;
}

function applyH(X, Y) {
  const h = Hnorm;
  const w = h[2][0] * X + h[2][1] * Y + h[2][2];
  return new THREE.Vector2(
    (h[0][0] * X + h[0][1] * Y + h[0][2]) / w,
    (h[1][0] * X + h[1][1] * Y + h[1][2]) / w
  );
}

function formatH(H) {
  return H.map(row => '[ ' + row.map(v => {
    const av = Math.abs(v) < 0.0005 ? 0 : v;
    return av.toFixed(3).padStart(7, ' ');
  }).join('  ') + ' ]').join('\n');
}

let cameraFramePts = [];
let imagePatchPts = [];
let surfacePts = [];
let camLabel, camPlaneLabel, imgPointLabel, worldPointLabel, planarLabel;
let labelX, labelY, labelZ, labelImgX, labelImgY;
let hLabel, imgPanelLabel, srcPanelLabel, img2DPointLabel, src2DPointLabel;
let fullLabels = [];
let h2dLabels = [];

function updateScene() {
  const tiltShift = 0.18 * Math.sin(tiltDeg * DEG);
  cameraFramePts = [
    v3(-1.52, -1.18, zBase),
    v3(0.55, 0.55 + tiltShift, zBase),
    v3(0.55, 2.58 + tiltShift, zBase),
    v3(-1.52, 0.85, zBase)
  ];
  imagePatchPts = [
    v3(-0.72, -0.55, zBase + 0.02),
    v3(0.29, 0.20 + 0.10 * Math.sin(tiltDeg * DEG), zBase + 0.02),
    v3(0.02, 1.06 + 0.10 * Math.sin(tiltDeg * DEG), zBase + 0.02),
    v3(-1.03, 0.46, zBase + 0.02)
  ];
  surfacePts = [
    applyTiltToSurfaceBase(0, 0),
    applyTiltToSurfaceBase(2.55, 0),
    applyTiltToSurfaceBase(2.55, 2.05),
    applyTiltToSurfaceBase(0, 2.05)
  ];
  setQuad(cameraFrameMesh, cameraFramePts);
  setOutline(cameraFrameOutline, cameraFramePts);
  setQuad(imagePatchMesh, imagePatchPts);
  setOutline(imagePatchOutline, imagePatchPts);
  setQuad(surfaceMesh, surfacePts);
  setOutline(surfaceOutline, surfacePts);

  cameraHandle.position.copy(cameraCenter);
  const Pworld = surfacePoint(P_LOCAL);
  const Pimg = imagePointFromLocal(P_LOCAL);
  worldPointMesh.position.copy(Pworld.clone().setZ(zPoint));
  imagePointMesh.position.copy(Pimg.clone().setZ(zPoint));

  setDashed(mainRay, [cameraCenter.clone(), Pimg.clone(), Pworld.clone().setZ(zLine)], 0.18, 0.11, 0.035);

  const farTargets = [
    surfacePts[3].clone().add(v3(0.25, 0.05, 0)),
    surfacePts[2].clone().add(v3(0.10, 0.16, 0)),
    surfacePts[1].clone().add(v3(0.20, -0.05, 0)),
    surfacePts[0].clone().add(v3(-0.05, -0.15, 0))
  ];
  for (let i = 0; i < 4; i++) {
    setDashed(frustumRays[i], [cameraCenter.clone(), cameraFramePts[i].clone().setZ(zLine), farTargets[i].clone().setZ(zLine)], 0.16, 0.10, 0.030);
  }

  const auxLocals = [
    new THREE.Vector2(0.70, 2.40),
    new THREE.Vector2(1.75, 0.35),
    new THREE.Vector2(2.35, 1.10)
  ];
  for (let i = 0; i < auxiliaryRays.length; i++) {
    const a = imagePointFromLocal(auxLocals[i]);
    const b = surfacePoint(auxLocals[i]);
    setDashed(auxiliaryRays[i], [cameraCenter.clone(), a.clone(), b.clone().setZ(zLine)], 0.14, 0.10, 0.026);
  }

  let gi = 0;
  for (let i = 1; i <= 4; i++) {
    const X = SRC_W * i / 5;
    setDashed(projectedGrid[gi++], [
      imagePointFromLocal(new THREE.Vector2(X, 0)),
      imagePointFromLocal(new THREE.Vector2(X, SRC_H))
    ], 0.09, 0.07, 0.018);
  }
  for (let j = 1; j <= 4; j++) {
    const Y = SRC_H * j / 5;
    setDashed(projectedGrid[gi++], [
      imagePointFromLocal(new THREE.Vector2(0, Y)),
      imagePointFromLocal(new THREE.Vector2(SRC_W, Y))
    ], 0.09, 0.07, 0.018);
  }

  const camOrigin = v3(-1.50, -1.62, zLine);
  setArrow2D(camXArrow, camOrigin, v3(0.78, 0.62, 0), 1.22);
  setArrow2D(camYArrow, camOrigin, v3(0, 1, 0), 1.62);

  const wOrigin = surfacePts[0].clone().add(v3(0.42, 0.28, zLine));
  setArrow2D(worldXArrow, wOrigin, v3(1, 0.28, 0), 0.93);
  setArrow2D(worldYArrow, wOrigin, v3(0.54, 0.82, 0), 0.88);
  setArrow2D(worldZArrow, wOrigin, v3(-0.40, 0.92, 0), 0.84);

  homographyMatrix();
  document.getElementById('matrixH').textContent = formatH(Hnorm);
  document.getElementById('tiltVal').textContent = `${Math.round(tiltDeg)}°`;
  document.getElementById('pointReadout').textContent = `(X,Y,0) = (${P_LOCAL.x.toFixed(2)}, ${P_LOCAL.y.toFixed(2)}, 0)`;

  if (camLabel) {
    camLabel.pos.copy(cameraCenter.clone().add(v3(-0.62, 0.05, 0.06)));
    camPlaneLabel.pos.copy(v3(-0.34, 1.77 + tiltShift, zPoint));
    imgPointLabel.pos.copy(Pimg.clone().add(v3(0.34, 0.16, 0.03)));
    worldPointLabel.pos.copy(Pworld.clone().add(v3(0.52, -0.42, 0.03)));
    planarLabel.pos.copy(surfacePts[2].clone().lerp(surfacePts[1], 0.52).add(v3(0.62, -0.02, 0.02)));
    labelImgX.pos.copy(camOrigin.clone().add(v3(1.08, -0.05, 0.04)));
    labelImgY.pos.copy(camOrigin.clone().add(v3(-0.22, 1.42, 0.04)));
    labelX.pos.copy(wOrigin.clone().add(v3(1.04, 0.28, 0.04)));
    labelY.pos.copy(wOrigin.clone().add(v3(0.67, 0.86, 0.04)));
    labelZ.pos.copy(wOrigin.clone().add(v3(-0.44, 0.94, 0.04)));
  }

  update2DView();
}

function makePanelRect(cx, cy, w, h, fillColor, opacity = 0.14) {
  const mesh = makeQuad(new THREE.MeshBasicMaterial({ color: fillColor, side: THREE.DoubleSide, transparent: true, opacity }));
  const outline = makeOutline(matBlack, 0.025);
  const pts = [
    v3(cx - w / 2, cy - h / 2, 0),
    v3(cx + w / 2, cy - h / 2, 0),
    v3(cx + w / 2, cy + h / 2, 0),
    v3(cx - w / 2, cy + h / 2, 0)
  ];
  setQuad(mesh, pts);
  setOutline(outline, pts);
  homoGroup.add(mesh, outline);
  return { pts, cx, cy, w, h };
}

const imgPanel = makePanelRect(-1.58, 0.35, 2.10, 1.50, 0x00e5ea, 0.12);
const srcPanel = makePanelRect(1.62, 0.35, 2.22, 1.40, 0xaaaaaa, 0.16);
const hArrow = makeArrow2D(matRed, 0.045, 0.22, 0.24);
homoGroup.add(hArrow);
setArrow2D(hArrow, v3(0.58, 0.35, 0.06), v3(-1, 0, 0), 1.28);

const img2DLines = [];
const src2DLines = [];
for (let i = 0; i < 8; i++) {
  const li = makeStrip(matCyanFaint);
  const ls = makeStrip(new THREE.MeshBasicMaterial({ color: 0x777777, side: THREE.DoubleSide, transparent: true, opacity: 0.55 }));
  img2DLines.push(li);
  src2DLines.push(ls);
  homoGroup.add(li, ls);
}
const img2DPoint = makePoint(0.075, 0.055);
const src2DPoint = makePoint(0.075, 0.055);
homoGroup.add(img2DPoint, src2DPoint);

function update2DView() {
  const imgCx = imgPanel.cx, imgCy = imgPanel.cy;
  const srcCx = srcPanel.cx, srcCy = srcPanel.cy;
  const srcScaleX = srcPanel.w / SRC_W;
  const srcScaleY = srcPanel.h / SRC_H;
  const imgScale = 0.72;
  let idx = 0;
  for (let i = 1; i <= 4; i++) {
    const X = SRC_W * i / 5;
    const x0 = srcCx - srcPanel.w / 2 + X * srcScaleX;
    setStrip(src2DLines[idx], v3(x0, srcCy - srcPanel.h / 2, 0.04), v3(x0, srcCy + srcPanel.h / 2, 0.04), 0.014);
    const a = applyH(X, 0);
    const b = applyH(X, SRC_H);
    setStrip(img2DLines[idx], v3(imgCx + a.x * imgScale, imgCy + a.y * imgScale, 0.05), v3(imgCx + b.x * imgScale, imgCy + b.y * imgScale, 0.05), 0.014);
    idx++;
  }
  for (let j = 1; j <= 4; j++) {
    const Y = SRC_H * j / 5;
    const y0 = srcCy - srcPanel.h / 2 + Y * srcScaleY;
    setStrip(src2DLines[idx], v3(srcCx - srcPanel.w / 2, y0, 0.04), v3(srcCx + srcPanel.w / 2, y0, 0.04), 0.014);
    const a = applyH(0, Y);
    const b = applyH(SRC_W, Y);
    setStrip(img2DLines[idx], v3(imgCx + a.x * imgScale, imgCy + a.y * imgScale, 0.05), v3(imgCx + b.x * imgScale, imgCy + b.y * imgScale, 0.05), 0.014);
    idx++;
  }
  const p = applyH(P_LOCAL.x, P_LOCAL.y);
  const srcPos = v3(srcCx - srcPanel.w / 2 + P_LOCAL.x * srcScaleX, srcCy - srcPanel.h / 2 + P_LOCAL.y * srcScaleY, zPoint);
  const imgPos = v3(imgCx + p.x * imgScale, imgCy + p.y * imgScale, zPoint);
  src2DPoint.position.copy(srcPos);
  img2DPoint.position.copy(imgPos);
  if (src2DPointLabel) src2DPointLabel.pos.copy(srcPos.clone().add(v3(0.30, 0.15, 0)));
  if (img2DPointLabel) img2DPointLabel.pos.copy(imgPos.clone().add(v3(0.26, 0.15, 0)));
}

updateScene();

