hLabel = addLabel('<b>H</b>', new THREE.Vector3(-0.05, 0.60, 0), { fontSize: '31px', color: '#111' });
imgPanelLabel = addLabel('image plane<br><i>(x,y)</i>', new THREE.Vector3(-1.58, -0.66, 0), { fontSize: '20px', color: '#111' });
srcPanelLabel = addLabel('world plane<br><i>(X,Y)</i>', new THREE.Vector3(1.62, -0.66, 0), { fontSize: '20px', color: '#111' });
img2DPointLabel = addLabel('<i>(x,y)</i>', new THREE.Vector3(), { fontSize: '20px', color: '#00dfe8', bold: true });
