function set2DCameraView() {
  setCameraView({
    projection: 'orthographic',
    azimuthDeg: 90,
    elevationDeg: 0,
    target: [0.0, 0.24, 0],
    heightFraction: 0.72,
    distanceScale: 1
  });
}

function setMode(to2D, refit = true) {
  mode2D = !!to2D;
  if (mode2D) {
    scene.remove(fullGroup);
    if (!homoGroup.parent) scene.add(homoGroup);
  } else {
    scene.remove(homoGroup);
    if (!fullGroup.parent) scene.add(fullGroup);
  }
  document.getElementById('projectionMode').textContent = mode2D ? 'View: 2D homography' : 'View: Full 3D projection';
  for (const l of fullLabels) l.div.style.visibility = mode2D ? 'hidden' : 'visible';
  for (const l of h2dLabels) l.div.style.visibility = mode2D ? 'visible' : 'hidden';
  if (refit) {
    if (mode2D) set2DCameraView();
    else setFullCameraView();
  }
}

setMode(false, false);

document.getElementById('planeTilt').addEventListener('input', (e) => {
  tiltDeg = Number(e.target.value);
  updateScene();
});

document.getElementById('projectionMode').addEventListener('click', () => {
  setMode(!mode2D, true);
});

const steps = [
  {
    title: 'Full projection geometry',
    narration: 'The cyan world point lies on the planar surface with coordinate (X,Y,0). A ray from the camera center passes through the camera plane at the cyan image point (x,y).',
    state: { planeTilt: 25, projectionMode: 'Full 3D projection' }
  },
  {
    title: 'Tilt the plane',
    narration: 'Changing the plane tilt skews the gray planar surface and changes the projected image grid. The correspondence is still described by one homography H because all world points have local Z=0.',
    state: { planeTilt: 55, projectionMode: 'Full 3D projection' }
  },
  {
    title: 'Collapse to homography',
    narration: 'The 3D construction collapses to a direct 2D mapping: source coordinates (X,Y) on the planar surface map to image coordinates (x,y) through H.',
    state: { planeTilt: 55, projectionMode: '2D homography' }
  }
];

let tweenToken = 0;
function goToStep(i) {
  const step = steps[i];
  if (!step) return;
  document.getElementById('stepNarration').innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  const startTilt = tiltDeg;
  const endTilt = step.state.planeTilt;
  const want2D = step.state.projectionMode === '2D homography';
  if (want2D !== mode2D) setMode(want2D, true);

  const start = performance.now();
  const token = ++tweenToken;
  function tick(now) {
    if (token !== tweenToken) return;
    const t = Math.min(1, (now - start) / 650);
    const ease = t * t * (3 - 2 * t);
    tiltDeg = startTilt + (endTilt - startTilt) * ease;
    document.getElementById('planeTilt').value = String(Math.round(tiltDeg));
    updateScene();
    if (t < 1) {
      requestAnimationFrame(tick);
    } else {
      tiltDeg = endTilt;
      document.getElementById('planeTilt').value = String(endTilt);
      updateScene();
      if (want2D) set2DCameraView();
      else setFullCameraView();
    }
  }
  requestAnimationFrame(tick);
}
window.goToStep = goToStep;

document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
document.getElementById('stepNarration').innerHTML = `<b>${steps[0].title}</b><br>${steps[0].narration}`;

const dragRaycaster = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();
let draggingCamera = false;
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), -cameraCenter.z);

function pointerToNDC(event) {
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
}

canvas.addEventListener('pointerdown', (event) => {
  if (mode2D) return;
  pointerToNDC(event);
  dragRaycaster.setFromCamera(dragPointer, camera);
  const hits = dragRaycaster.intersectObject(cameraSphere, false);
  if (hits.length) {
    draggingCamera = true;
    controls.enabled = false;
    dragPlane.set(new THREE.Vector3(0, 0, 1), -cameraCenter.z);
    canvas.setPointerCapture?.(event.pointerId);
  }
});

canvas.addEventListener('pointermove', (event) => {
  if (!draggingCamera) return;
  pointerToNDC(event);
  dragRaycaster.setFromCamera(dragPointer, camera);
  const hit = new THREE.Vector3();
  if (dragRaycaster.ray.intersectPlane(dragPlane, hit)) {
    cameraCenter.x = THREE.MathUtils.clamp(hit.x, -2.85, -1.38);
    cameraCenter.y = THREE.MathUtils.clamp(hit.y, 0.48, 1.78);
    cameraCenter.z = 0.24;
    updateScene();
  }
});

window.addEventListener('pointerup', (event) => {
  if (!draggingCamera) return;
  draggingCamera = false;
  controls.enabled = true;
  canvas.releasePointerCapture?.(event.pointerId);
});
